const resaleTypes = ['clothing','book','ornament','jewellery'];
const typeNames: Row = {clothing:'Clothes',book:'Books',shoes:'Shoes',hat:'Hats',jewellery:'Jewellery',ornament:'Ornaments',homeware:'Homeware',toy:'Toys',bag:'Bags',other:'Other'};
