 const filterItems=items.filter((x:Row)=>(page!=='Warehouse'||!processingBag||x.donation_id===processingBag)&&(page!=='Warehouse'||x.category===category)&&(type==='all'||x.item_type===type)&&matchesItemStatus(x,status)&&(!query||`${x.title} ${x.reference} ${x.details.brand||''} ${x.location}`.toLowerCase().includes(query.toLowerCase()))).sort((a:Row,b:Row)=>b.created_at.localeCompare(a.created_at));
 const activeItems=items.filter((x:Row)=>!['sold','donated','disposed'].includes(x.status));
 const awaiting=donations.filter((x:Row)=>x.status==='sorting');
 const openSort=(id='')=>{const chosen=id||processingBag;if(!chosen||!data?.donations.some((b:Row)=>b.id===chosen&&b.status==='sorting')){setBagStage('active');setModal('bags');return;}setProcessingBag(chosen);setSortBag(chosen);setReclassify(null);setModal('sort');};
