  {page==='Warehouse'&&<div className="bag-workspace"><ShoppingBag size={23}/><div><b>{currentBag?`Processing ${currentBag.reference}`:'Choose the donation bag in front of you'}</b><small>{currentBag?`${donorFor(currentBag)?.name||'Anonymous donor'} · ${labels[currentBag.status]} · ${items.filter((x:Row)=>x.donation_id===currentBag.id).length} items recorded`:'Scan its QR or select a bag above. Every item and photo stays linked to that lot.'}</small></div><div className="bag-workspace-actions">{currentBag?.status==='sorting'&&<button className="button primary" onClick={()=>openSort(currentBag.id)}><Plus size={16}/>Sort next item</button>}{currentBag&&<button className="button secondary" onClick={()=>setSelected({kind:'donation',id:currentBag.id})}>Bag details</button>}<button className="button secondary" onClick={()=>chooseBags('active')}>{currentBag?'Change bag':'Select bag'}</button><button className="button secondary" onClick={()=>{setExpectedScanBag('');setModal('scan');}}><ScanLine size={16}/>Scan bag</button>{currentBag&&<button className="icon-button" aria-label="Show items from all bags" onClick={()=>setProcessingBag('')}><X size={18}/></button>}</div></div>}
